import { NextResponse } from 'next/server';

export function middleware(request) {
  // 1. Read an incoming header
  const language = request.headers.get('accept-language');

  // 2. Read an incoming cookie
  const theme = request.cookies.get('theme');

  // 3. Create the response object early so we can modify it
  const response = NextResponse.next();

  // 4. Set a new cookie to send BACK to the browser
  response.cookies.set('visited', 'true', {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
  });

  // 5. Append a new header to send DOWNSTREAM to our Next.js pages
  response.headers.set('x-user-language', language);

  return response;
}
